"""Score a Vue corpus app and its React twin against the same ground truth.

usage: python3 -I compare_twins.py VUE_APP_DIR VUE_SNAPSHOT REACT_APP_DIR REACT_SNAPSHOT [--details OUT.json]

VUE_APP_DIR holds expected.json. REACT_APP_DIR holds twin-map.json:
{
  "vue_ext": ".tsx",                          # extension that replaces .vue by default
  "files": {"src/App.vue": "src/App.tsx"},    # explicit file renames (optional)
  "names": {"src/views/X.vue#created": "componentDidMount"},  # symbol renames keyed by Vue file#name
  "no_counterpart": {"<fact key>": "reason"}  # facts React has no equivalent for
}
Fact keys are printed by --keys and match vue_corpus_test.go.
"""
import json
import os
import re
import sys
from collections import defaultdict


def load_snapshot(path):
    symbols, files, externals, relations = [], {}, defaultdict(list), []
    for line in open(path):
        record = json.loads(line)
        kind = record.get("record_type")
        if kind == "symbol":
            symbols.append(record)
        elif kind == "file":
            files[record["path"]] = record["id"]
        elif kind == "external":
            externals[record["value"]].append(record["id"])
        elif kind == "relation":
            relations.append(record)
    by_file = defaultdict(list)
    for symbol in symbols:
        by_file[symbol["file_path"]].append(symbol)
    rel_index = defaultdict(set)
    for relation in relations:
        rel_index[relation["type"]].add((relation["from_id"], relation["to_id"]))
    from_index = defaultdict(set)
    for relation in relations:
        from_index[relation["type"]].add(relation["from_id"])
    return {"by_file": by_file, "files": files, "externals": externals, "rels": rel_index, "from": from_index}


def types_of(value):
    return value if isinstance(value, list) else [value]


def endpoint_key(endpoint):
    if endpoint.get("external"):
        return "ext:" + endpoint["external"]
    if not endpoint.get("name"):
        return endpoint["file"]
    if endpoint.get("kind"):
        return f'{endpoint["file"]}#{endpoint["name"]}:{endpoint["kind"]}'
    return f'{endpoint["file"]}#{endpoint["name"]}'


def symbol_key(fact):
    base = f'symbol {fact["file"]}#{fact["name"]}'
    return base + (":" + fact["kind"] if fact.get("kind") else "")


def facts_of(manifest):
    for fact in manifest["symbols"]:
        yield "symbol", fact["tag"], symbol_key(fact), fact
    for fact in manifest.get("absent_symbols", []):
        yield "absent_symbol", fact["tag"], f'absent {fact["file"]}#{fact["name"]}', fact
    for fact in manifest["relations"]:
        key = "|".join(types_of(fact["type"])) + " " + endpoint_key(fact["from"]) + " -> " + endpoint_key(fact["to"])
        yield "relation", fact["tag"], "relation " + key, fact
    for fact in manifest.get("absent_relations", []):
        to = endpoint_key(fact["to"]) if fact.get("to") else "*"
        key = "|".join(types_of(fact["type"])) + " " + endpoint_key(fact["from"]) + " -> " + to
        yield "absent_relation", fact["tag"], "absent " + key, fact


def endpoint_ids(snapshot, endpoint, strict_kind=True, line=None):
    if endpoint.get("external"):
        return set(snapshot["externals"].get(endpoint["external"], []))
    if not endpoint.get("name"):
        file_id = snapshot["files"].get(endpoint["file"])
        return {file_id} if file_id else set()
    ids = set()
    for symbol in snapshot["by_file"].get(endpoint["file"], []):
        if symbol["name"] != endpoint["name"]:
            continue
        if strict_kind and endpoint.get("kind") and symbol["kind"] != endpoint["kind"]:
            continue
        if line is not None and not (symbol["start_line"] <= line <= max(symbol.get("end_line", 0), symbol["start_line"])):
            continue
        ids.add(symbol["id"])
    return ids


def evaluate(snapshot, category, fact, strict=True):
    if category == "symbol":
        return bool(endpoint_ids(snapshot, fact, strict, fact.get("line") if strict else None))
    if category == "absent_symbol":
        return not endpoint_ids(snapshot, fact, strict)
    types = types_of(fact["type"])
    from_ids = endpoint_ids(snapshot, fact["from"], strict)
    if category == "relation":
        to_ids = endpoint_ids(snapshot, fact["to"], strict)
        return any((a, b) in snapshot["rels"][t] for t in types for a in from_ids for b in to_ids)
    if fact.get("to"):
        to_ids = endpoint_ids(snapshot, fact["to"], strict)
        return not any((a, b) in snapshot["rels"][t] for t in types for a in from_ids for b in to_ids)
    return not any(a in snapshot["from"][t] for t in types for a in from_ids)


class TwinMap:
    def __init__(self, react_root):
        data = json.load(open(os.path.join(react_root, "twin-map.json")))
        self.root = react_root
        self.vue_ext = data.get("vue_ext", ".tsx")
        self.files = data.get("files", {})
        self.names = data.get("names", {})
        self.no_counterpart = data.get("no_counterpart", {})
        self.errors = []
        self._text = {}

    def file(self, path):
        if path in self.files:
            return self.files[path]
        return path[:-4] + self.vue_ext if path.endswith(".vue") else path

    def endpoint(self, endpoint, key):
        if endpoint.get("external"):
            return dict(endpoint)
        mapped = {"file": self.file(endpoint["file"])}
        full = os.path.join(self.root, mapped["file"])
        if not os.path.isfile(full):
            self.errors.append(f"{key}: mapped file {mapped['file']} does not exist")
            return mapped
        if endpoint.get("name"):
            vue_ref = f'{endpoint["file"]}#{endpoint["name"]}'
            name = self.names.get(vue_ref, endpoint["name"])
            mapped["name"] = name
            # Vue-only kinds (component/document/element) carry no meaning in the twin.
            if endpoint.get("kind") and endpoint["kind"] not in ("component", "document", "element"):
                mapped["kind"] = endpoint["kind"]
            text = self._text.setdefault(full, open(full, encoding="utf-8").read())
            if not re.search(r"(^|[^A-Za-z0-9_$])" + re.escape(name) + r"([^A-Za-z0-9_$]|$)", text):
                self.errors.append(f"{key}: {name} never appears in {mapped['file']}")
        return mapped

    def fact(self, category, fact, key):
        if category in ("symbol", "absent_symbol"):
            mapped = self.endpoint(fact, key)
            mapped["tag"] = fact["tag"]
            return mapped
        mapped = {"type": fact["type"], "from": self.endpoint(fact["from"], key), "tag": fact["tag"]}
        if fact.get("to"):
            mapped["to"] = self.endpoint(fact["to"], key)
        return mapped


def main(argv):
    if "--keys" in argv:
        manifest = json.load(open(os.path.join(argv[argv.index("--keys") + 1], "expected.json")))
        for category, tag, key, _ in facts_of(manifest):
            print(f"{tag}\t{key}")
        return 0
    vue_root, vue_snap, react_root, react_snap = argv[1:5]
    details_path = argv[argv.index("--details") + 1] if "--details" in argv else None
    manifest = json.load(open(os.path.join(vue_root, "expected.json")))
    vue = load_snapshot(vue_snap)
    react = load_snapshot(react_snap)
    twin = TwinMap(react_root)

    rows = defaultdict(lambda: {"total": 0, "vue": 0, "na": 0, "comparable": 0, "react": 0, "vue_on_comparable": 0})
    details = []
    unknown_na = set(twin.no_counterpart) - {key for _, _, key, _ in facts_of(manifest)}
    for key in sorted(unknown_na):
        twin.errors.append(f"no_counterpart key matches no fact: {key}")
    for category, tag, key, fact in facts_of(manifest):
        row = rows[tag]
        row["total"] += 1
        vue_ok = evaluate(vue, category, fact, strict=True)
        row["vue"] += vue_ok
        entry = {"tag": tag, "key": key, "vue": vue_ok}
        if key in twin.no_counterpart:
            row["na"] += 1
            entry["react"] = "n/a"
            entry["why"] = twin.no_counterpart[key]
        else:
            mapped = twin.fact(category, fact, key)
            react_ok = evaluate(react, category, mapped, strict=False)
            row["comparable"] += 1
            row["react"] += react_ok
            row["vue_on_comparable"] += vue_ok
            entry["react"] = react_ok
            entry["mapped"] = mapped
        details.append(entry)

    print(f"{'tag':<20} {'facts':>5} {'vue':>5} | {'n/a':>4} {'comparable':>10} {'react':>6} {'vue':>5}")
    totals = defaultdict(int)
    for tag in sorted(rows):

