    25	export function buildUrl(path: string, query?: Query): string {
    26	  const url = new URL(BASE_URL + path, window.location.origin)
    27	  if (query) {
    28	    for (const [key, value] of Object.entries(query)) {
    29	      if (value !== undefined) {
