    41	  }
    42	  const response = await fetch(buildUrl(path, query), {
    43	    method,
    44	    headers,
    45	    body: body === undefined ? undefined : JSON.stringify(body),
    46	  })
    47	  if (!response.ok) {
    48	    throw new ApiError(response.status, await response.text())
    49	  }
