    10	
    11	export class EventBus<Events extends Record<string, unknown>> {
    12	  private handlers = new Map<keyof Events, Set<Handler<never>>>()
    13	
    14	  on<K extends keyof Events>(event: K, handler: Handler<Events[K]>): () => void {
    15	    const set = this.handlers.get(event) ?? new Set()
    16	    set.add(handler as Handler<never>)
    17	    this.handlers.set(event, set)
    18	    return () => this.off(event, handler)
    19	  }
    20	
    21	  off<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
    22	    this.handlers.get(event)?.delete(handler as Handler<never>)
    23	  }
    24	
    25	  emit<K extends keyof Events>(event: K, payload: Events[K]): void {
    26	    for (const handler of this.handlers.get(event) ?? []) {
    27	      ;(handler as Handler<Events[K]>)(payload)
    28	    }
    29	  }
    30	}
