  session: null,
  restoring: false,
  lastError: null,
  isAuthenticated: (): boolean => get().session !== null,
  currentUser: (): User | null => get().session?.user ?? null,
  isAdmin(): boolean {
    return isPrivileged(get().currentUser())
  },
