import { create } from 'zustand'
import { createTask, deleteTask, fetchTasks, postTaskMove, updateTask } from '@/api/tasks'
import type { Task, TaskDraft, TaskMovedPayload } from '@/types/task'
import { bus } from '@/utils/eventBus'

interface TaskState {
  tasks: Task[]
  loading: boolean
  error: string | null
  tasksByColumn: () => Record<string, Task[]>
  findTask: (taskId: string) => Task | undefined
  loadTasks: (projectId: string) => Promise<void>
  addTask: (projectId: string, draft: TaskDraft) => Promise<Task>
  editTask: (taskId: string, changes: Partial<Task>) => Promise<Task>
  removeTask: (taskId: string) => Promise<void>
  moveTask: (payload: TaskMovedPayload) => Promise<void>
}

export const useTaskStore = create<TaskState>()((set, get) => {
  const tasksByColumn = () => {
    const groups: Record<string, Task[]> = {}
    for (const task of get().tasks) {
      ;(groups[task.columnId] ??= []).push(task)
    }
    for (const list of Object.values(groups)) {
      list.sort((a, b) => a.position - b.position)
    }
    return groups
  }

  function findTask(taskId: string): Task | undefined {
    return get().tasks.find((task) => task.id === taskId)
  }

  async function loadTasks(projectId: string) {
    set({ loading: true, error: null })
    try {
      set({ tasks: await fetchTasks(projectId) })
    } catch (err) {
      set({ error: err instanceof Error ? err.message : String(err) })
    } finally {
      set({ loading: false })
    }
  }

  async function addTask(projectId: string, draft: TaskDraft) {
    const task = await createTask(projectId, draft)
    set({ tasks: [...get().tasks, task] })
    bus.emit('task:created', task)
    return task
  }

  async function editTask(taskId: string, changes: Partial<Task>) {
    const updated = await updateTask(taskId, changes)
    const index = get().tasks.findIndex((task) => task.id === taskId)
    if (index !== -1) {
      set({ tasks: get().tasks.map((task, i) => (i === index ? updated : task)) })
    }
    return updated
  }

  async function removeTask(taskId: string) {
    await deleteTask(taskId)
    set({ tasks: get().tasks.filter((task) => task.id !== taskId) })
    bus.emit('task:deleted', taskId)
  }

  async function moveTask(payload: TaskMovedPayload) {
    const task = findTask(payload.taskId)
    if (!task) {
      return
    }
    const previous = { columnId: task.columnId, position: task.position }
    set({ tasks: get().tasks.map((item) => (item.id === task.id ? { ...item, columnId: payload.toColumnId, position: payload.position } : item)) })
    try {
      await postTaskMove(payload)
    } catch {
      set({ tasks: get().tasks.map((item) => (item.id === task.id ? { ...item, ...previous } : item)) })
    }
  }

  return { tasks: [], loading: false, error: null, tasksByColumn, findTask, loadTasks, addTask, editTask, removeTask, moveTask }
})
