import { useEffect, useMemo, useState } from 'react'

export function clampPage(target: number, pageCount: number): number {
  return Math.min(Math.max(1, target), Math.max(1, pageCount))
}

export function usePagination<T>(items: T[], pageSize: number) {
  const [page, setPage] = useState(1)
  const pageCount = useMemo(() => Math.max(1, Math.ceil(items.length / pageSize)), [items.length, pageSize])
  const pageItems = useMemo(() => {
    const start = (page - 1) * pageSize
    return items.slice(start, start + pageSize)
  }, [items, page, pageSize])

  function goTo(target: number) {
    setPage(clampPage(target, pageCount))
  }

  function next() {
    goTo(page + 1)
  }

  function prev() {
    goTo(page - 1)
  }

  useEffect(() => {
    if (page > pageCount) {
      goTo(pageCount)
    }
  }, [pageCount])

  return { page, pageCount, pageItems, goTo, next, prev }
}
