import { useMemo, useState, type DragEvent as ReactDragEvent, type ReactNode } from 'react'
import type { Column } from '@/types/project'
import type { Task, TaskMovedPayload } from '@/types/task'
import { useDragDrop } from '../composables/useDragDrop'
import { pluralize } from '@/utils/format'
import TaskCard from './TaskCard'

export default function BoardColumn(props: {
  column: Column
  tasks: Task[]
  selectedTaskId?: string | null
  onTaskMoved?: (payload: TaskMovedPayload) => void
  onTaskSelected?: (task: Task) => void
  onTaskToggled?: (taskId: string, done: boolean) => void
  title?: (slot: { column: Column; count: number }) => ReactNode
  footer?: (slot: { column: Column }) => ReactNode
}) {
  const { overColumnId, startDrag, dragOver, drop, endDrag } = useDragDrop((payload) => props.onTaskMoved?.(payload))

  const [collapsed, setCollapsed] = useState(false)
  const isOver = useMemo(() => overColumnId === props.column.id, [overColumnId, props.column.id])
  const overLimit = useMemo(
    () => props.column.wipLimit !== null && props.tasks.length > props.column.wipLimit,
    [props.column.wipLimit, props.tasks.length],
  )

  function countLabel(): string {
    return pluralize(props.tasks.length, 'task')
  }

  function onDragStart(event: DragEvent, taskId: string) {
    startDrag(event, taskId, props.column.id)
  }

  function onDrop(event: ReactDragEvent<HTMLElement>) {
    event.preventDefault()
    drop(props.column.id, props.tasks.length)
  }

  function onSelect(task: Task) {
    props.onTaskSelected?.(task)
  }

  function onToggleDone(taskId: string, done: boolean) {
    props.onTaskToggled?.(taskId, done)
  }

  function toggleCollapsed() {
    setCollapsed(!collapsed)
  }

  return (
    <section
      className={['board-column', isOver && 'is-over', collapsed && 'is-collapsed', overLimit && 'over-limit'].filter(Boolean).join(' ')}
      data-column-id={props.column.id}
      onDragOver={(event) => {
        event.preventDefault()
        dragOver(props.column.id)
      }}
      onDrop={onDrop}
    >
      <header className="board-column__header">
        <button type="button" className="board-column__toggle" onClick={toggleCollapsed}>
          {props.title ? props.title({ column: props.column, count: props.tasks.length }) : <h2>{props.column.title}</h2>}
        </button>
        <span className="board-column__count">{countLabel()}</span>
      </header>
      <ol className="board-column__list" hidden={collapsed}>
        {props.tasks.map((task) => (
          <li key={task.id}>
            <TaskCard
              task={task}
              selected={task.id === props.selectedTaskId}
              onSelect={onSelect}
              onToggleDone={onToggleDone}
              onDragStart={onDragStart}
              onDragEnd={endDrag}
            />
          </li>
        ))}
      </ol>
      {props.footer?.({ column: props.column })}
    </section>
  )
}
