import { useEffect, useState, type FormEvent } from 'react'
import { fetchComments, postComment } from '@/api/comments'
import { usePagination } from '@/composables/usePagination'
import { useAuthStore } from '@/stores/auth'
import type { Comment } from '@/types/task'
import BaseButton from '@/components/base/BaseButton'
import CommentItem from './CommentItem'
import PaginationBar from './PaginationBar'

export default function CommentList(props: { taskId: string }) {
  const auth = useAuthStore()
  const [comments, setComments] = useState<Comment[]>([])
  const [draft, setDraft] = useState('')
  const [posting, setPosting] = useState(false)
  const [pageSize] = useState(5)
  const commentInputId = `comment-input-${props.taskId}`
  const { pageItems, page, pageCount, next, prev } = usePagination(comments, pageSize)

  async function load() {
    setComments(await fetchComments(props.taskId))
  }

  async function submitComment(event: FormEvent) {
    event.preventDefault()
    const body = draft.trim()
    if (!body) {
      return
    }
    setPosting(true)
    try {
      const comment = await postComment(props.taskId, body)
      setComments([comment, ...comments])
      setDraft('')
    } finally {
      setPosting(false)
    }
  }

  function startReply(comment: Comment) {
    setDraft(`@${comment.author.name} `)
  }

  useEffect(() => {
    load()
  }, [props.taskId])

  return (
    <section className="comment-list" aria-label="Comments">
      <ol>
        {pageItems.map((comment) => (
          <CommentItem
            key={comment.id}
            comment={comment}
            own={comment.author.id === auth.currentUser()?.id}
            onReply={startReply}
            actions={({ comment: item }) => (
              <button type="button" className="comment__reply" onClick={() => startReply(item)}>
                Reply
              </button>
            )}
          />
        ))}
      </ol>
      {pageCount > 1 && <PaginationBar page={page} pageCount={pageCount} onNext={next} onPrev={prev} />}
      {auth.isAuthenticated() && (
        <form className="comment-list__form" onSubmit={submitComment}>
          <label htmlFor={commentInputId} className="visually-hidden">
            Comment
          </label>
          <textarea id={commentInputId} value={draft} onChange={(event) => setDraft(event.target.value)} rows={3} placeholder="Add a comment" />
          <BaseButton type="submit" variant="primary" loading={posting}>
