import { relativeDueLabel } from '@/utils/format'
import BaseButton from '@/components/base/BaseButton'
import LabelBadge from './LabelBadge'

const CommentList = lazy(() => import('./CommentList'))

export default function TaskDetailPanel(props: { taskId: string; onClose?: () => void }) {
  const board = useContext(BoardContextKey)
  if (!board) {
    throw new Error('TaskDetailPanel must be rendered inside a board')
  }

  const store = useTaskStore()
  const task = useMemo(() => store.findTask(props.taskId) ?? null, [store, props.taskId])

  function dueText(): string {
    return task ? relativeDueLabel(task.dueDate) : ''
  }

  async function removeLabel(labelId: string) {
    if (!task) {
      return
    }
    await store.editTask(task.id, { labels: task.labels.filter((label) => label.id !== labelId) })
  }

  async function deleteCurrent() {
    if (!task) {
      return
    }
    await store.removeTask(task.id)
    props.onClose?.()
  }

  if (!task) {
    return null
  }

  return (
    <aside className="task-detail" aria-labelledby="task-detail-title">
      <header className="task-detail__header">
        <h2 id="task-detail-title">{task.title}</h2>
        <BaseButton variant="ghost" aria-label="Close" onClick={() => props.onClose?.()}>
          Close
