      </header>
      <p className="task-detail__due">{dueText()}</p>
      <div className="task-detail__labels">
        {task.labels.map((label) => (
          <LabelBadge key={label.id} label={label} removable onRemove={removeLabel} />
        ))}
      </div>
      <section className="task-detail__description">{task.description}</section>
      <Suspense fallback={null}>
        <CommentList taskId={task.id} />
      </Suspense>
