import { useEffect, useMemo, type ChangeEvent, type HTMLAttributes } from 'react'
import { useNavigate } from 'react-router-dom'
import { useProjectStore } from '@/stores/projects'
import type { Project } from '@/types/project'

export interface SwitcherOption {
  value: string
  label: string
}

export function toOption(project: Project): SwitcherOption {
  return { value: project.id, label: `${project.key} - ${project.name}` }
}

export default function ProjectSwitcher({ compact = false, ...attrs }: { compact?: boolean } & HTMLAttributes<HTMLDivElement>) {
  const navigate = useNavigate()
  const projectStore = useProjectStore()
  const activeProjects = projectStore.activeProjects()
  const { currentProjectId } = projectStore
  const { loadProjects, selectProject } = projectStore

  const options = useMemo(() => activeProjects.map(toOption), [activeProjects])

  async function onChange(event: ChangeEvent<HTMLSelectElement>) {
    const projectId = event.target.value
    await selectProject(projectId)
    navigate(`/projects/${projectId}/board`)
  }

  useEffect(() => {
    if (activeProjects.length === 0) {
      loadProjects()
    }
  }, [])

  return (
    <div className={compact ? 'project-switcher compact' : 'project-switcher'} {...attrs}>
      <label className="visually-hidden" htmlFor="project-select">
        Project
      </label>
      <select id="project-select" value={currentProjectId ?? ''} onChange={onChange}>
        <option value="" disabled>
          Select a project
        </option>
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </div>
  )
}
