interface Props {
  task: Task
  draggable?: boolean
  selected?: boolean
  compact?: boolean
  onSelect?: (task: Task) => void
  onToggleDone?: (taskId: string, done: boolean) => void
  onDragStart?: (event: DragEvent, taskId: string) => void
  onDragEnd?: () => void
}

export default function TaskCard(props: Props) {
  const { draggable = true, selected = false, compact = false } = props

  const isDone = useMemo(() => props.task.status === 'done', [props.task.status])

  function overdue(): boolean {
    return isOverdue(props.task)
  }

  function dueLabel(): string {
    return formatDate(props.task.dueDate)
  }

  function select() {
    props.onSelect?.(props.task)
  }

  function toggleDone() {
    props.onToggleDone?.(props.task.id, !isDone)
  }

  const onDragStart = (event: ReactDragEvent<HTMLElement>) => {
    props.onDragStart?.(event.nativeEvent, props.task.id)
  }

  return (
    <article
      className={['task-card', selected && 'is-selected', overdue() && 'is-overdue', isDone && 'is-done', compact && 'compact'].filter(Boolean).join(' ')}
      data-task-id={props.task.id}
