  }

  function clearAll() {
    props.onChange?.('')
    props.onClear?.()
  }

  return (
    <form className="task-filters" role="search" onSubmit={(event) => event.preventDefault()}>
      <label htmlFor="filter-search" className="visually-hidden">
        Search tasks
