import { useEffect, type ReactNode } from 'react'
import { createPortal } from 'react-dom'

export default function BaseModal(props: {
  title: string
  width?: string
  open?: boolean
  onOpenChange?: (open: boolean) => void
  header?: (slot: { close: () => void }) => ReactNode
  footer?: (slot: { close: () => void }) => ReactNode
  children?: ReactNode
}) {
  const { width = '32rem' } = props

  const open = props.open ?? false

  function close() {
    props.onOpenChange?.(false)
  }

  function onKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape' && open) {
      close()
    }
  }

  useEffect(() => {
    window.addEventListener('keydown', onKeydown)
    return () => window.removeEventListener('keydown', onKeydown)
  })

  return createPortal(
    open && (
      <div
        className="modal-backdrop"
        onClick={(event) => {
          if (event.target === event.currentTarget) close()
        }}
      >
        <section className="modal" role="dialog" aria-modal="true" aria-label={props.title} style={{ width }}>
          <header className="modal-header">
            {props.header ? props.header({ close }) : <h2 className="modal-title">{props.title}</h2>}
            <button type="button" className="modal-close" aria-label="Close" onClick={close}>
              x
            </button>
          </header>
          <div className="modal-body">{props.children}</div>
          {props.footer && <footer className="modal-footer">{props.footer({ close })}</footer>}
        </section>
      </div>
    ),
    document.body,
  )
}
