import { useEffect, useMemo, useRef, useState } from 'react'
import { useParams, useSearchParams } from 'react-router-dom'
import BaseButton from '@/components/base/BaseButton'
import BaseModal from '@/components/base/BaseModal'
import BoardColumn from '@/components/BoardColumn'
import TaskDetailPanel from '@/components/TaskDetailPanel'
import TaskFilters from '@/components/TaskFilters'
import TaskForm, { type TaskFormHandle } from '@/components/TaskForm'
import { useFilters } from '@/composables/useFilters'
import { useAuthStore } from '@/stores/auth'
import { useProjectStore } from '@/stores/projects'
import { useTaskStore } from '@/stores/tasks'
import { BoardContextKey } from '@/keys'
import type { Task, TaskDraft, TaskMovedPayload } from '@/types/task'

export default function BoardView() {
  const props = useParams() as { projectId: string }

  const [query, setQuery_] = useSearchParams()
  const auth = useAuthStore()
  const taskStore = useTaskStore()
  const projectStore = useProjectStore()
  const { tasks, loading } = taskStore
  const { board, members } = projectStore
  const currentProject = projectStore.currentProject()
  const { filters, filteredTasks, activeCount, setQuery, togglePriority, clearFilters } = useFilters(tasks)

  const [searchText, setSearchText] = useState('')
  const [showForm, setShowForm] = useState(false)
  const taskForm = useRef<TaskFormHandle | null>(null)
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null)

  const columns = useMemo(() => board?.columns ?? [], [board])
  const canEdit = useMemo(
    () => auth.isAdmin() || currentProject?.members.some((member) => member.id === auth.currentUser()?.id) === true,
    [auth, currentProject],
  )

  function tasksFor(columnId: string): Task[] {
    return filteredTasks.filter((task) => task.columnId === columnId)
  }

  function openTask(task: Task) {
    setSelectedTaskId(task.id)
    setQuery_({ ...Object.fromEntries(query), task: task.id }, { replace: true })
  }

  function closeTask() {
    setSelectedTaskId(null)
    const { task: _task, ...rest } = Object.fromEntries(query)
    setQuery_(rest, { replace: true })
  }

  async function onTaskMoved(payload: TaskMovedPayload) {
    await taskStore.moveTask(payload)
  }

  async function onTaskToggled(taskId: string, done: boolean) {
    await taskStore.editTask(taskId, { status: done ? 'done' : 'todo' })
  }

  async function openNewTask() {
    setShowForm(true)
    await taskForm.current?.focusTitle()
  }

  async function createFromDraft(draft: TaskDraft) {
    await taskStore.addTask(props.projectId, draft)
    setShowForm(false)
    taskForm.current?.reset()
  }

  useEffect(() => setQuery(searchText), [searchText])

  useEffect(() => {
    const taskId = query.get('task')
    setSelectedTaskId(typeof taskId === 'string' ? taskId : null)
  }, [query])

  useEffect(() => {
    ;(async () => {
      await projectStore.selectProject(props.projectId)
      await taskStore.loadTasks(props.projectId)
    })()
  }, [])

  return (
    <BoardContextKey.Provider value={{ board, canEdit, openTask }}>
      <div id="board-root" className="board-view">
        <header className="board-view__header">
          <h1>{currentProject?.name ?? 'Board'}</h1>
          <TaskFilters
            value={searchText}
            onChange={setSearchText}
            filters={filters}
            activeCount={activeCount}
            onTogglePriority={togglePriority}
            onClear={clearFilters}
          />
          {canEdit && (
            <BaseButton variant="primary" onClick={openNewTask}>
              New task
            </BaseButton>
          )}
        </header>
        {loading ? (
          <p className="board-view__loading">Loading tasks...</p>
        ) : (
          <div id="board-columns" className="board-view__columns">
            {columns.map((column) => (
              <BoardColumn
                key={column.id}
                column={column}
                tasks={tasksFor(column.id)}
                selectedTaskId={selectedTaskId}
                onTaskMoved={onTaskMoved}
